# Protocol steps
sample = "aquatic_sample"
place_sample_into_tube(sample, sample_vol="1 mL")
add_iron_chloride_solution(sample, iron_chl_solution_vol="1 μL")
centrifuge_sample(sample, rcf="14K", time="20 minutes")
remove_supernatant(sample, pipette_method="leave pellet undisturbed")
dissolve_pellet(sample, buffer_vol="10 μL", buffer_type="Ascorbic-EDTA")
mix_sample_and_buffer(sample, vortex_method="vortex and pipette")
add_stain_and_incubate(sample, stain_vol="2 μL", incubation_time="15 minutes", dark=True)

# If sample is unconcentrated
add_antifade_solution(sample, antifade_solution_vol="1 μL")

add_glycerol(sample, glycerol_vol="5 μL")
add_working_bead_solution(sample, working_bead_solution_vol="2 µL")
clean_glass_slide_and_coverslip(clean_method="isopropanol and Kimwipes")
dispense_sample_onto_slide(sample, sample_vol="10 μL")
place_coverslip(sample)
count_viruses_microscope(sample, excitation_wavelength="495 nm", magnification="1000X")
count_beads_microscope(sample, light_type="white light", magnification="1000X")
repeat_counting_viruses_beads(sample, n_virus, n_beads, times="multiple fields until at least 100 of each are counted")
calculate_virus_concentration(sample, n_virus, n_beads, v_beads, v_sample, c_beads)
store_prepared_samples(sample, storage_temp="-20ºC")
# end of protocol

